-- Modify "app_deploy_configs" table
ALTER TABLE "public"."app_deploy_configs" ADD CONSTRAINT "app_deploy_configs_build_context_check" CHECK ((build_context = ''::text) OR ((char_length(build_context) <= 200) AND (build_context ~ '^[A-Za-z0-9._/-]+$'::text) AND (build_context !~ '\.\.'::text) AND (build_context !~ '^/'::text))), ADD CONSTRAINT "app_deploy_configs_build_env_check" CHECK ((jsonb_typeof(build_env) = 'array'::text) AND (octet_length((build_env)::text) <= 4096)), ADD CONSTRAINT "app_deploy_configs_dockerfile_path_check" CHECK ((dockerfile_path = ''::text) OR ((char_length(dockerfile_path) <= 200) AND (dockerfile_path ~ '^[A-Za-z0-9._/-]+$'::text) AND (dockerfile_path !~ '\.\.'::text) AND (dockerfile_path !~ '^/'::text))), ADD COLUMN "dockerfile_path" text NOT NULL DEFAULT '', ADD COLUMN "build_context" text NOT NULL DEFAULT '', ADD COLUMN "build_env" jsonb NOT NULL DEFAULT '[]';
